import{_ as i,o as t,c as a,a0 as e}from"./chunks/framework.BZ80FTt7.js";const c=JSON.parse('{"title":"两套自瞄策略的实战切换","description":"","frontmatter":{},"headers":[],"relativePath":"blog/2026-07-25-auto-aim-policy-comparison.md","filePath":"blog/2026-07-25-auto-aim-policy-comparison.md"}'),n={name:"blog/2026-07-25-auto-aim-policy-comparison.md"};function l(h,s,p,d,r,k){return t(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="两套自瞄策略的实战切换" tabindex="-1">两套自瞄策略的实战切换 <a class="header-anchor" href="#两套自瞄策略的实战切换" aria-label="Permalink to &quot;两套自瞄策略的实战切换&quot;">​</a></h1><p>今天没有继续堆新功能，而是把两套已经能运行的自瞄策略放进同一个仿真场景对比：原有的 <code>baseline</code>，以及参考上科大开源自瞄思路做的 <code>shtech</code> 实验策略。</p><p>这里的重点不是给某套算法贴上“更强”的标签，而是把它放到可复现的条件下，看看它在什么情况下有用、什么时候和原方案其实走的是同一条路径。</p><h2 id="两套策略怎么分工" tabindex="-1">两套策略怎么分工 <a class="header-anchor" href="#两套策略怎么分工" aria-label="Permalink to &quot;两套策略怎么分工&quot;">​</a></h2><p><code>baseline</code> 是原项目已有的流程：目标检测后进入旋转目标 EKF，接着由 Aimer 计算提前量，Shooter 在误差满足条件时开火。</p><p><code>shtech</code> 是我新加的双策略切换层。它会估计目标的角速度：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>低转速：装甲板位置与速度预测 -&gt; Trajectory 解算 -&gt; 开火</span></span>
<span class="line"><span>过渡区：低速装甲分支与旋转目标分支的云台角度混合</span></span>
<span class="line"><span>高转速：旋转目标 EKF + MPC Planner</span></span></code></pre></div><p>阈值目前是：低于 <code>1.57 rad/s</code> 用装甲分支，高于 <code>2.1 rad/s</code> 用高速旋转分支，中间做平滑过渡。这样做的原因很直接：静止或缓慢运动的装甲板，没有必要套完整的旋转体模型；前哨站高速转动时，只看一块装甲板又会失去稳定性，需要保留原有的旋转目标状态估计。</p><p>这不是对 SHtech 整个自瞄系统的逐行移植。当前版本借鉴的是“根据目标运动状态选择合适跟踪模型”的做法，完整的 IESEKF 实现并没有直接搬进来。</p><h2 id="同条件实战结果" tabindex="-1">同条件实战结果 <a class="header-anchor" href="#同条件实战结果" aria-label="Permalink to &quot;同条件实战结果&quot;">​</a></h2><p>每一局都会重启游戏，目标从 <code>1500 HP</code> 开始；哨兵站位、视觉模型、交战窗口均相同，只有 <code>--aim-policy</code> 参数不同。结束时还会检查 <code>release_restored=true</code>，确认外部程序没有把云台控制权留在游戏里。</p><table tabindex="0"><thead><tr><th>场景</th><th>策略</th><th style="text-align:right;">子弹</th><th style="text-align:right;">有效命中</th><th style="text-align:right;">命中率</th><th style="text-align:right;">伤害</th><th style="text-align:right;">检测率</th></tr></thead><tbody><tr><td>冻结前哨，低转速</td><td><code>baseline</code></td><td style="text-align:right;">46</td><td style="text-align:right;">42</td><td style="text-align:right;">91.3%</td><td style="text-align:right;">840</td><td style="text-align:right;">90.8%</td></tr><tr><td>冻结前哨，低转速</td><td><code>shtech</code></td><td style="text-align:right;">46</td><td style="text-align:right;">42</td><td style="text-align:right;">91.3%</td><td style="text-align:right;">840</td><td style="text-align:right;">89.7%</td></tr><tr><td>原生旋转前哨，约 <code>2.5 rad/s</code></td><td><code>baseline</code></td><td style="text-align:right;">45</td><td style="text-align:right;">14</td><td style="text-align:right;">31.1%</td><td style="text-align:right;">280</td><td style="text-align:right;">65.1%</td></tr><tr><td>原生旋转前哨，约 <code>2.5 rad/s</code></td><td><code>shtech</code></td><td style="text-align:right;">46</td><td style="text-align:right;">14</td><td style="text-align:right;">30.4%</td><td style="text-align:right;">280</td><td style="text-align:right;">82.3%</td></tr></tbody></table><p>低转速下，两者的伤害和命中率完全相同。高速旋转时，<code>shtech</code> 的检测率更高，但有效命中仍然是 14 次。原因不是切换失效，恰好相反：高速区间里 <code>shtech</code> 会主动回到旋转目标 EKF 与 MPC 路径，所以两套策略在这一段的核心瞄准逻辑相同。</p><p>这轮结果说明两件事：低速装甲分支可以稳定开火；当前实现还没有带来高速旋转目标的命中提升。后者是下一步需要继续验证和调参的地方，不能因为检测率更高就把它说成性能提升。</p><h2 id="我怎么验证切换真的发生" tabindex="-1">我怎么验证切换真的发生 <a class="header-anchor" href="#我怎么验证切换真的发生" aria-label="Permalink to &quot;我怎么验证切换真的发生&quot;">​</a></h2><p>为了让“切换”不是代码里的一个 <code>if</code>，我加了一个冻结前哨的基准场景：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">bench_freeze_outpost</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>它会让红方前哨停止旋转，角速度接近 <code>0 rad/s</code>。此时 <code>shtech</code> 必须选择低速装甲分支。原生前哨保持约 <code>2.5 rad/s</code> 转速时，则进入高速旋转分支。两个场景都能造成伤害，并且结束后控制权能交还，才算这套策略具备继续迭代的基础。</p><p>运行时可以这样选择：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 原有策略</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">gestalt.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ws_port</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> configs\\gestalt_sentry_outpost_static.yaml </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">\`</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">setup</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fire</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">timeout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">showui</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">aim</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">policy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">baseline</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 双策略实验版本</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">gestalt.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ws_port</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> configs\\gestalt_sentry_outpost_static.yaml </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">\`</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">setup</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fire</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">timeout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">showui</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">aim</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">policy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">shtech</span></span></code></pre></div><p><code>&lt;ws_port&gt;</code> 每次启动游戏都会变化，应从游戏日志中查找 <code>WebSocket server started</code>，不能复用上次的端口。</p><h2 id="从-c-语法开始-怎么学这部分" tabindex="-1">从 C++ 语法开始，怎么学这部分 <a class="header-anchor" href="#从-c-语法开始-怎么学这部分" aria-label="Permalink to &quot;从 C++ 语法开始，怎么学这部分&quot;">​</a></h2><p>如果只学过 C++ 语法，我建议不要从 EKF 公式或 MPC 推导硬读起。先把一次实际开火拆成四个问题，读代码时每次只回答一个。</p><ol><li><strong>目标在哪里？</strong> 从 YOLO 检测框开始，理解它只告诉我们图像中的位置；再看 PnP 如何用装甲板尺寸和相机参数还原三维坐标。</li><li><strong>目标下一刻在哪里？</strong> 看 <code>Tracker</code> 和 <code>ShtechArmorTracker</code> 的输入、状态和输出。前者适合旋转体，后者只平滑位置、速度和偏航变化。</li><li><strong>云台该转多少？</strong> 读 <code>Trajectory</code> 与 Aimer。它们把未来目标位置变成 yaw、pitch，并把子弹飞行时间算进去。</li><li><strong>什么时候允许开火？</strong> 看 <code>Shooter</code> 和 <code>command.shoot</code>。开火不是检测到目标就扣扳机，而是要等云台角度足够接近解算结果。</li></ol><p>比较代码时，也先盯住一条很短的调用链：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/gestalt.cpp</span></span>
<span class="line"><span>  -&gt; 选择 baseline / shtech</span></span>
<span class="line"><span>  -&gt; Tracker 或 ShtechArmorTracker</span></span>
<span class="line"><span>  -&gt; Trajectory / Planner</span></span>
<span class="line"><span>  -&gt; command.shoot</span></span>
<span class="line"><span>  -&gt; GameLink 发送到游戏</span></span></code></pre></div><p>把程序以 <code>--fire=0</code> 跑一遍，只观察日志里的角速度、策略选择和云台角度；理解后再开启 <code>--fire=1</code>，对照 HP、子弹数和有效命中。这样学到的每个类和函数都能回到游戏画面里验证，不会只停留在语法层面。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>下一轮会补充策略选择日志，明确记录每一帧处于 <code>armor</code>、<code>blend</code> 还是 <code>vehicle</code> 模式；然后在多个不同转速下重复测试，而不是只看静止和约 <code>2.5 rad/s</code> 两端。只有拿到转速与命中率的曲线，才有资格调整阈值或说某套策略更合适。</p>`,29)])])}const g=i(n,[["render",l]]);export{c as __pageData,g as default};
